head.script:
scwin.checkVal = function() {
    return WebSquare.wUnit.getDomById($p.id + 'btn').getAttribute('class') == " w2trigger_anchor ";
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 0. trigger type='anchor', anchorWithGroupClass='false'로 설정한다.
    //Set trigger type = 'anchor' and anchorWithGroupClass = 'false'.
    //Test step 1. 샘플파일을 개발자모드(F12)에서 실행 후 요소검사에서 검색어(class)로 검색한다.
    //1. Run the sample file in developer mode (F12) and search for the class in the element check.
    //Verify 1. class = 'w2trigger_anchor'로 보여진다. (즉, w2group가 없이 보여진다.)
    //1. It is shown as class = 'w2trigger_anchor'. (Ie, without w2group).
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 05-Feb-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
